{
  "name": "@turnprune/opencode",
  "version": "0.1.3",
  "description": "TurnPrune for OpenCode: replaces tool outputs the agent no longer needs with a fixed placeholder, once per user turn.",
  "license": "MIT",
  "type": "module",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "source": "./src/index.ts",
      "default": "./dist/index.js"
    },
    "./server": {
      "types": "./dist/index.d.ts",
      "source": "./src/index.ts",
      "default": "./server.js"
    },
    "./tui": {
      "types": "./dist/tui.d.ts",
      "default": "./tui.js"
    }
  },
  "files": [
    "dist",
    "server.js",
    "tui.js",
    "cli.js",
    "README.md",
    "LICENSE"
  ],
  "engines": {
    "node": ">=22.13.0"
  },
  "dependencies": {
    "@turnprune/core": "0.1.3"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/guschi18/turnprune.git",
    "directory": "packages/opencode"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "context",
    "prompt-cache",
    "jev",
    "openrouter"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.json"
  },
  "main": "./server.js",
  "bin": {
    "turnprune": "cli.js"
  },
  "publishConfig": {
    "access": "public"
  }
}
